import React, { useState, useEffect } from 'react';
import './LoadingSpinner.css';
import imageLoader from '../../utils/imageLoader';

const LoadingSpinner = ({ isLoading = true, onFinish, criticalImages = [] }) => {
    const [shouldFadeOut, setShouldFadeOut] = useState(false);
    const [loadingProgress, setLoadingProgress] = useState(0);
    const [loadingText, setLoadingText] = useState('Loading...');

    useEffect(() => {
        if (!isLoading) {
            // Start fade out animation
            setShouldFadeOut(true);
            const timer = setTimeout(() => {
                if (onFinish) onFinish();
            }, 500); // Increased fade out time for smoother transition

            return () => clearTimeout(timer);
        }
    }, [isLoading, onFinish]);

    useEffect(() => {
        if (criticalImages.length > 0) {
            loadCriticalImages();
        }
    }, [criticalImages]);

    const loadCriticalImages = async () => {
        try {
            setLoadingText('Loading critical resources...');

            // Preload critical images
            const results = await imageLoader.preloadCriticalImages(criticalImages);

            // Calculate progress
            const loadedCount = results.filter(r => r.status === 'loaded').length;
            const progress = (loadedCount / criticalImages.length) * 100;

            setLoadingProgress(progress);

            if (progress === 100) {
                setLoadingText('Ready!');
                // Small delay to show completion
                setTimeout(() => {
                    setShouldFadeOut(true);
                    if (onFinish) onFinish();
                }, 300);
            }
        } catch (error) {
            console.error('Error loading critical images:', error);
            // Continue anyway after a delay
            setTimeout(() => {
                setShouldFadeOut(true);
                if (onFinish) onFinish();
            }, 1000);
        }
    };

    return (
        <div className={`loader-wrapper ${shouldFadeOut ? 'fade-out' : ''}`}>
            <div className="wrapper">
                <div className="box-wrap">
                    <div className="box one"></div>
                    <div className="box two"></div>
                    <div className="box three"></div>
                    <div className="box four"></div>
                    <div className="box five"></div>
                    <div className="box six"></div>
                </div>
            </div>

            <div className="loader-content">
                <div className="logo-container">
                    <img
                        src="https://i.imgur.com/Lg3kv0j.png"
                        alt="ECESS Logo"
                        className="logo-image responsive-logo"
                    />
                </div>

                {criticalImages.length > 0 && (
                    <div className="loading-info">
                        <div className="loading-text">{loadingText}</div>
                        <div className="progress-bar">
                            <div 
                                className="progress-fill" 
                                style={{ width: `${loadingProgress}%` }}
                            ></div>
                        </div>
                        <div className="progress-text">{Math.round(loadingProgress)}%</div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default LoadingSpinner;
